import app from 'flarum/common/app';
let maps = [];
let request = null;

/** The traced stadium charts a seller may pick, once loadSeatMaps() has run. */
export function seatMaps() {
  return maps;
}

/** Fetches the offered charts once per page load; a failure retries next time. */
export function loadSeatMaps() {
  return request ||= app.request({
    method: 'GET',
    url: app.forum.attribute('apiUrl') + '/classifieds/seatmaps/offered'
  }).then(r => maps = r.data || [], () => {
    request = null;
    return maps;
  });
}
flarum.reg.add('ernestdefoe-classifieds', 'common/utils/seatMaps', { seatMaps: seatMaps,loadSeatMaps: loadSeatMaps, });